package org.usbworkbench;
import android.app.*;import android.content.*;import android.os.*;
import java.io.*;import java.util.*;
/** Debug-only owned cache fixtures. No Activity, USB enumeration, UI, preferences or real-drive access. */
public final class AnalyzerSmokeTest extends Instrumentation {
 private int checks;
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 private void yes(boolean value,String message){if(!value)throw new AssertionError(message);checks++;}
 private void wimRoot(Context c)throws Exception{
  File f=File.createTempFile("owned-wim-root-",".wim",c.getCacheDir());try{
   try(InputStream in=c.getAssets().open("owned-root.wim");OutputStream out=new FileOutputStream(f)){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}
   try(RandomAccessFile file=new RandomAccessFile(f,"r")){OpticalImage.Source source=new OpticalImage.Source(){public long size()throws IOException{return file.length();}public void read(long at,byte[] b,int off,int n)throws IOException{file.seek(at);file.readFully(b,off,n);}public void close(){}};
    ArchiveTools.Manifest m=ArchiveTools.scanWim(new File(c.getApplicationInfo().nativeLibraryDir),source,1,"/",16L*1048576,(a,b)->{},()->false);
    boolean outside=false,nested=false;for(ArchiveTools.Entry e:m.entries){outside|=e.path.equals("outside.txt");nested|=e.path.equals("folder/hello.txt");}yes(outside,"actual WIM root includes outside file");yes(nested,"actual WIM root includes nested file");
    Map<String,ArchiveTools.MemoryFile> outputs=new HashMap<>();Map<String,String> hashes=ArchiveTools.extract(new File(c.getApplicationInfo().nativeLibraryDir),source,m,new WimFiles.Store(){public WimFiles.RandomFile create(String n){ArchiveTools.MemoryFile x=new ArchiveTools.MemoryFile();outputs.put(n,x);return x;}public void capacity(long n){}},(a,b)->{},()->false);
    for(ArchiveTools.Entry e:m.entries)if(e.path.equals("folder/hello.txt"))yes(Arrays.equals(outputs.get(e.output()).data(),"USB Workbench manual test.\n".getBytes("UTF-8")),"actual WIM root extraction bytes");
    yes(!hashes.isEmpty(),"WIM readback hashes");
   }
   yes(WimPaths.normalize(" /folder/hello.txt ",false).equals("/folder/hello.txt"),"WIM outer spaces normalized");
   try{WimPaths.normalize("/ /folder/hello.txt",false);throw new AssertionError("blank component accepted");}catch(IOException e){yes(e.getMessage().equals("WIM_FILE_PATH"),"ambiguous WIM path refused before writes");}
   yes(OutputNames.unique("samples",Arrays.asList("samples")).equals("samples (2)"),"friendly collision suffix");
  }finally{yes(f.delete(),"owned WIM sample cleaned");}
 }
 private void bench(Context c)throws Exception{
  File file=File.createTempFile("owned-partition-edit-",".img",c.getCacheDir());try{try(RandomAccessFile image=new RandomAccessFile(file,"rw")){image.setLength(64L*1048576);BlockDevice disk=new BlockDevice(){public int blockSize(){return 512;}public long blockCount(){return 131072;}public void read(long at,byte[] b,int n)throws IOException{image.seek(at*512);image.readFully(b,0,n);}public void write(long at,byte[] b,int n)throws IOException{image.seek(at*512);image.write(b,0,n);}public void sync()throws IOException{image.getFD().sync();}public void close(){}};
   AdvancedDiskTools.installGpt(disk,2048,131038,"OLD");byte[] data=new byte[16384];new Random(19).nextBytes(data);disk.write(2048,data,data.length);String edited=PartitionMetadata.apply(disk,PartitionMetadata.plan(disk,"gptName",1,"بيانات USB"),(a,b)->{});yes(edited.startsWith("PARTITION_EDIT_OK"),"GPT metadata edit");yes(AdvancedDiskTools.inspectGpt(disk).contains("بيانات USB"),"GPT both CRCs and Arabic name");byte[] saved=new byte[data.length];disk.read(2048,saved,saved.length);yes(Arrays.equals(data,saved),"volume bytes preserved");yes(PartitionMetadata.apply(disk,PartitionMetadata.plan(disk,"gptName",1,"بيانات USB"),(a,b)->{}).equals("PARTITION_EDIT_UNCHANGED"),"matching metadata no-op");yes(ReportText.render(edited,true).contains("اسم قسم GPT")&&!ReportText.render(edited,true).contains("written"),"selected-language edit report");
   byte[] m=new byte[512];m[450]=7;DiskTools.le32(m,454,2048);DiskTools.le32(m,458,10000);m[510]=85;m[511]=(byte)170;disk.write(0,m,512);PartitionMetadata.apply(disk,PartitionMetadata.plan(disk,"mbrActive",1,""),(a,b)->{});byte[] active=new byte[512];disk.read(0,active,512);m[446]=(byte)128;yes(Arrays.equals(m,active),"MBR exact active flag only");
  }}finally{yes(file.delete(),"owned metadata fixture cleaned");}
  byte[] packed={(byte)0x82,65,66,67,0,2,0x40,0,5};ByteArrayOutputStream out=new ByteArrayOutputStream();try(AdcInputStream in=new AdcInputStream(new ByteArrayInputStream(packed))){byte[] b=new byte[3];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}yes(Arrays.equals(out.toByteArray(),"ABCABCABCA".getBytes(java.nio.charset.StandardCharsets.US_ASCII)),"ADC literal/short/long stream");
  try(AdcInputStream in=new AdcInputStream(new ByteArrayInputStream(new byte[]{0,0}))){in.read();throw new AssertionError("ADC reference accepted");}catch(IOException e){yes(e.getMessage().equals("DMG_DATA"),"invalid ADC reference denied");}
 }
 private void adcContainer()throws Exception{
  byte[] data=android.util.Base64.decode("",android.util.Base64.DEFAULT);OpticalImage.Source source=new OpticalImage.Source(){public long size(){return data.length;}public void read(long at,byte[] b,int off,int n)throws IOException{if(at<0||n>data.length-at)throw new IOException("BOUNDS");System.arraycopy(data,(int)at,b,off,n);}public void close(){}};
  yes(DmgConverter.budget(source,1024,(a,b)->{})==1024,"ADC UDIF preflight on Android SAX");ByteArrayOutputStream output=new ByteArrayOutputStream();ImageContainers.Result converted=DmgConverter.convert(source,output,1024,(a,b)->{});byte[] plain=output.toByteArray();yes(plain.length==1024,"ADC UDIF exact expansion");for(int i=0;i<plain.length;i++)if(plain[i]!=(byte)(i*17+3))throw new AssertionError("ADC payload mismatch");checks++;
  OpticalImage.Source saved=new OpticalImage.Source(){public long size(){return plain.length;}public void read(long at,byte[] b,int off,int n){System.arraycopy(plain,(int)at,b,off,n);}public void close(){}};ImageContainers.verify("dmgRaw",saved,converted,(a,b)->{});yes(true,"ADC UDIF output digest readback");
 }
 private void formatProgress(Context c)throws Exception{
  WorkbenchApp app=(WorkbenchApp)c.getApplicationContext();String job=app.job,phase=app.phase;long total=app.total,done=app.done;boolean cancel=app.cancel;IoMetrics old=app.formatIo;
  File file=File.createTempFile("owned-ntfs-progress-",".img",c.getCacheDir());try{app.job="format";app.phase="ntfs_metadata";app.total=-1;app.done=0;app.cancel=false;IoMetrics metrics=new IoMetrics();app.formatIo=metrics;
   yes(!app.progressText().contains("0%"),"unknown format notification never0percent");yes(ReportText.phase("usb_open",true).contains("USB"),"USB opening phase localized");
   try(RandomAccessFile image=new RandomAccessFile(file,"rw")){image.setLength(64L*1048576);BlockDevice disk=new BlockDevice(){public int blockSize(){return 512;}public long blockCount(){return 131072;}public void read(long at,byte[] b,int n)throws IOException{image.seek(at*512);image.readFully(b,0,n);}public void write(long at,byte[] b,int n)throws IOException{image.seek(at*512);image.write(b,0,n);}public void sync()throws IOException{image.getFD().sync();}public void close(){}};
    java.util.List<String> phases=new java.util.ArrayList<>();NativeFormat.format(c,metrics.wrap(disk),"ntfs","gpt","ورشة",0,app::progress,()->false,value->{app.formatStage(value);phases.add(value);if(app.total!=-1)throw new AssertionError("phase retains false percentage");});
    yes(phases.contains("ntfs_metadata")&&phases.contains("filesystem_verify")&&phases.get(phases.size()-1).equals("partition_commit"),"real formatter stages");yes(metrics.writeBytes>0&&metrics.writeBytes<8L*1048576&&metrics.readBytes>0,"quick physical IO diagnostics");yes(metrics.reads+metrics.writes<1000,"bounded physical request count for64MiBNTFS");
    NtfsInspector.inspect(new SliceDevice(disk,2048,disk.blockCount()-2048-33));yes(AdvancedDiskTools.inspectGpt(disk).contains("CRC OK"),"verified NTFS and bothGPTcopies");yes(app.progressText().contains("100%"),"known final stage percentage");metrics.freeze();long fixed=metrics.idleMillis();yes(metrics.idleMillis()==fixed,"completed diagnostics freeze");
   }
  }finally{app.job=job;app.phase=phase;app.total=total;app.done=done;app.cancel=cancel;app.formatIo=old;yes(file.delete(),"owned NTFS progress fixture cleaned");}
 }
 @android.annotation.SuppressLint("UsableSpace")
 @Override public void onStart(){Bundle result=new Bundle();File current=null;try{
  Context c=getTargetContext();yes(c.getCacheDir().getUsableSpace()>640L*1048576,"owned fixture space");File libs=new File(c.getApplicationInfo().nativeLibraryDir);
  for(String fs:new String[]{"fat12","fat16","fat32","exfat","ntfs","ext2","ext3","ext4","f2fs","udf","hfsplus","apfs","btrfs","xfs"}){
   current=File.createTempFile("owned-usb-analysis-",".img",c.getCacheDir());long size=(fs.equals("xfs")?512L:((fs.equals("f2fs")||fs.equals("apfs")||fs.equals("btrfs"))?256L:fs.equals("fat12")?16L:(fs.equals("fat32")||fs.equals("exfat"))?128L:64L))*1048576;
   try(RandomAccessFile image=new RandomAccessFile(current,"rw")){image.setLength(size);BlockDevice disk=new BlockDevice(){public int blockSize(){return 512;}public long blockCount(){return size/512;}public void read(long at,byte[] b,int n)throws IOException{image.seek(at*512);image.readFully(b,0,n);}public void write(long at,byte[] b,int n)throws IOException{image.seek(at*512);image.write(b,0,n);}public void sync()throws IOException{image.getFD().sync();}public void close(){}};
    String label=fs.equals("ntfs")||fs.startsWith("ext")?"ورشة":"OWNED";
    if(NativeFormat.supports(fs))NativeFormat.format(c,disk,fs,"gpt",label,0,(a,b)->{},()->false);else AdvancedDiskTools.format(disk,fs,"gpt",label,0,(a,b)->{});
   }
   final long[] requests={0};final int[] forbidden={0};try(RandomAccessFile image=new RandomAccessFile(current,"r")){
    BlockDevice readonly=new BlockDevice(){public int blockSize(){return 512;}public long blockCount(){return size/512;}public void read(long at,byte[] b,int n)throws IOException{if(at<0||n<0||n%512!=0||at>blockCount()||n/512>blockCount()-at)throw new IOException("BOUNDS");requests[0]+=n;image.seek(at*512);image.readFully(b,0,n);}public void write(long at,byte[] b,int n)throws IOException{forbidden[0]++;throw new IOException("READ_ONLY");}public void sync()throws IOException{forbidden[0]++;throw new IOException("READ_ONLY");}public void close(){}};
    String raw=new UsbAnalyzer(readonly,(a,b)->{},part->ArchiveTools.statistics(libs,new UsbFileSource(part),(a,b)->{},()->false)).analyze();String en=ReportText.render(raw,false),ar=ReportText.render(raw,true);
    yes(en.contains("Partition table: GPT")&&en.contains("GPT copies agree: Yes"),"verified GPT "+fs);
    yes(!en.contains("analysis incomplete"),"complete volume analysis "+fs+" "+en);
    yes(forbidden[0]==0&&requests[0]<=64L*1048576,"read-only budget "+fs);
    yes(ar.contains("جدول الأقسام")&&!ar.contains("Free space")&&!ar.contains("Partition table"),"Arabic labels "+fs);
    yes((fs.equals("f2fs")||ExtraFormat.supports(fs))?en.contains("Unavailable"):en.contains("Free space:"),"space source "+fs);
    if(fs.equals("ntfs")){yes(en.contains("NTFS allocation bitmap")&&en.contains("Volume label: ورشة"),"NTFS native stats Unicode label");}
    if(fs.startsWith("ext"))yes(en.contains("Volume label: ورشة")&&en.contains("Reserved blocks"),"ext Unicode/counters "+fs);
    try{new UsbAnalyzer(readonly,(a,b)->{throw new IOException("CANCELLED");}).analyze();throw new AssertionError("Missing cancellation");}catch(IOException e){yes("CANCELLED".equals(e.getMessage()),"cancel "+fs);}
   }
   yes(current.delete(),"owned fixture cleanup "+fs);current=null;
  }
  bench(c);adcContainer();formatProgress(c);wimRoot(c);
  result.putString("stream","PASS: "+checks+" background Android analyzer/bench checks on fourteen generated filesystems; zero physical USB access, no Activity or preference changes.\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL after "+checks+" background analyzer checks: "+e+"\n");finish(Activity.RESULT_CANCELED,result);}finally{if(current!=null&&current.exists())current.delete();}}
}
